package io.kestra.plugin.datadog.api;

import com.fasterxml.jackson.databind.JsonNode;
import io.kestra.core.serializers.JacksonMapper;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPInputStream;

/** The pinned OpenAPI operation catalog. Generated by scripts/gen-catalog.py. */
public final class Catalog {
    private final List<Operation> operations;
    private final Map<String, Operation> qualified = new LinkedHashMap<>();
    private final Map<String, List<Operation>> byId = new LinkedHashMap<>();

    private Catalog(JsonNode root) {
        if (root.path("formatVersion").asInt() != 1) {
            throw new IllegalStateException("Unsupported Datadog catalog format");
        }
        List<Operation> rows = new ArrayList<>();
        for (JsonNode row : root.path("operations")) {
            Operation op = new Operation(row);
            if (qualified.put(op.key(), op) != null) {
                throw new IllegalStateException("Duplicate catalog operation " + op.key());
            }
            byId.computeIfAbsent(op.id(), ignored -> new ArrayList<>()).add(op);
            rows.add(op);
        }
        operations = List.copyOf(rows);
    }

    private static final class Holder {
        private static final Catalog INSTANCE = load();
    }

    public static Catalog get() {
        return Holder.INSTANCE;
    }

    private static Catalog load() {
        InputStream input = Catalog.class.getResourceAsStream("/datadog/operations.json");
        try {
            if (input == null) {
                InputStream compressed = Catalog.class.getResourceAsStream("/datadog/operations.json.gz");
                if (compressed == null) {
                    throw new IllegalStateException("Datadog operation catalog is missing");
                }
                input = new GZIPInputStream(compressed);
            }
            try (InputStream stream = input) {
                return new Catalog(JacksonMapper.ofJson().readTree(stream));
            }
        } catch (IOException e) {
            throw new IllegalStateException("Cannot read Datadog operation catalog", e);
        }
    }

    public List<Operation> operations() {
        return operations;
    }

    public Operation operation(String id) {
        if (id == null || id.isBlank()) {
            throw new IllegalArgumentException("Datadog `operationId` must not be blank");
        }
        if (qualified.containsKey(id)) {
            return qualified.get(id);
        }
        List<Operation> matches = byId.getOrDefault(id, List.of());
        if (matches.isEmpty()) {
            throw new IllegalArgumentException("Unknown Datadog operationId " + id);
        }
        if (matches.size() > 1) {
            throw new IllegalArgumentException("Ambiguous Datadog operationId " + id + ": use " +
                String.join(" or ", matches.stream().map(Operation::key).toList()));
        }
        return matches.getFirst();
    }

    public record Operation(JsonNode definition) {
        public String id() { return definition.path("operationId").asText(); }
        public String api() { return definition.path("api").asText(); }
        public String key() { return api() + ":" + id(); }
        public String tag() { return definition.path("tag").asText(); }
        public String method() { return definition.path("method").asText(); }
        public String path() { return definition.path("path").asText(); }
        public boolean deprecated() { return definition.path("deprecated").asBoolean(); }
        public boolean bodyRequired() { return definition.path("bodyRequired").asBoolean(); }
        public JsonNode parameters() { return definition.path("parameters"); }
        public JsonNode parameter(String location, String name) {
            for (JsonNode p : parameters()) {
                if (p.path("in").asText().equals(location) && p.path("name").asText().equals(name)) {
                    return p;
                }
            }
            return null;
        }
        public IllegalArgumentException invalid(String problem) {
            return new IllegalArgumentException("Datadog " + key() + ": " + problem);
        }
    }
}
